<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Stock alert generated by the alert evaluation engine (UC-05).
 * Types: low_stock, critical_stock, near_expiry, expired.
 *
 * @uc UC-05 @fr FR-2.6, 2.7, 9.1 @br BR-08, BR-19 @ac AC-33
 */
class StockAlert extends Model
{
    use HasFactory;

    protected $fillable = [
        'product_id',
        'batch_id',
        'type',
        'severity',
        'threshold_days',
        'current_quantity',
        'reorder_level',
        'min_level',
        'message',
        'status',
        'seen_at',
        'seen_by',
        'dedupe_key',
    ];

    protected function casts(): array
    {
        return [
            'threshold_days' => 'integer',
            'current_quantity' => 'integer',
            'reorder_level' => 'integer',
            'min_level' => 'integer',
            'seen_at' => 'datetime',
        ];
    }

    public function product(): BelongsTo
    {
        return $this->belongsTo(Product::class);
    }

    public function batch(): BelongsTo
    {
        return $this->belongsTo(Batch::class);
    }

    public function seenByUser(): BelongsTo
    {
        return $this->belongsTo(User::class, 'seen_by');
    }

    public function scopeActive(Builder $query): Builder
    {
        return $query->where('status', '!=', 'resolved');
    }

    public function scopeUnseen(Builder $query): Builder
    {
        return $query->where('status', 'active');
    }

    public function scopeType(Builder $query, ?string $type): Builder
    {
        return $type ? $query->where('type', $type) : $query;
    }
}
